create extension if not exists pgcrypto;

create type public.publish_state as enum ('draft', 'published', 'archived');
create type public.rsvp_attendance as enum ('attending', 'declined', 'unsure');
create type public.moderation_state as enum ('pending', 'approved', 'rejected', 'hidden');

create table public.admin_users (id uuid primary key references auth.users(id) on delete cascade, email text not null unique, created_at timestamptz not null default now());
create table public.site_settings (id uuid primary key default gen_random_uuid(), site_title text not null default 'Nhứt & Ngân | Our Wedding', canonical_url text, primary_event_id uuid, envelope_enabled boolean not null default true, music_enabled boolean not null default false, state public.publish_state not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.couple_profiles (id uuid primary key default gen_random_uuid(), groom_name text not null default 'Bùi Thanh Nhứt', bride_name text not null default 'Trần Thị Mỹ Ngân', hero_message text, story text, state public.publish_state not null default 'draft', updated_at timestamptz not null default now());
create table public.families (id uuid primary key default gen_random_uuid(), side text not null check (side in ('groom','bride')), display_name text, content text, state public.publish_state not null default 'draft', unique(side));
create table public.content_sections (id uuid primary key default gen_random_uuid(), section_key text not null unique, title text, body text, sort_order integer not null default 0, visible boolean not null default true, state public.publish_state not null default 'draft', updated_at timestamptz not null default now());
create table public.locations (id uuid primary key default gen_random_uuid(), venue_name text, address text, description text, maps_url text check (maps_url is null or maps_url ~ '^https://'), directions_note text, state public.publish_state not null default 'draft');
create table public.events (id uuid primary key default gen_random_uuid(), title text not null, starts_at timestamptz, ends_at timestamptz, timezone text not null default 'Asia/Ho_Chi_Minh', ceremony_type text, location_id uuid references public.locations(id) on delete set null, is_primary boolean not null default false, state public.publish_state not null default 'draft', check (ends_at is null or starts_at is null or ends_at > starts_at));
alter table public.site_settings add constraint site_settings_primary_event_fk foreign key (primary_event_id) references public.events(id) on delete set null;
create unique index events_one_primary on public.events ((is_primary)) where is_primary;
create table public.event_timeline_items (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, title text not null, description text, starts_at timestamptz, icon text, sort_order integer not null default 0, state public.publish_state not null default 'draft');
create table public.albums (id uuid primary key default gen_random_uuid(), title text not null, description text, cover_asset_id uuid, sort_order integer not null default 0, visible boolean not null default false, created_at timestamptz not null default now());
create table public.media_assets (id uuid primary key default gen_random_uuid(), storage_path text not null unique, original_filename text not null, mime_type text not null check (mime_type like 'image/%' or mime_type like 'audio/%'), bytes bigint not null check (bytes > 0), checksum text, alt_text text, is_original boolean not null default true, created_at timestamptz not null default now());
alter table public.albums add constraint albums_cover_asset_fk foreign key (cover_asset_id) references public.media_assets(id) on delete set null;
create table public.album_photos (album_id uuid not null references public.albums(id) on delete cascade, asset_id uuid not null references public.media_assets(id) on delete restrict, sort_order integer not null default 0, visible boolean not null default false, primary key (album_id,asset_id));
create table public.rsvp_submissions (id uuid primary key default gen_random_uuid(), guest_name text not null check (char_length(guest_name) between 2 and 100), contact text, attendance public.rsvp_attendance not null, guest_count smallint not null default 0 check (guest_count between 0 and 10), message text check (char_length(message) <= 500), consent text not null, confirmation_code text not null unique, internal_notes text, created_at timestamptz not null default now(), check ((attendance <> 'declined') or guest_count = 0));
create table public.rsvp_event_selections (rsvp_id uuid not null references public.rsvp_submissions(id) on delete cascade, event_id uuid not null references public.events(id) on delete restrict, primary key (rsvp_id,event_id));
create table public.guestbook_messages (id uuid primary key default gen_random_uuid(), display_name text not null check (char_length(display_name) between 2 and 60), message text not null check (char_length(message) between 3 and 500), consent text, consent_public_display boolean not null default false, status public.moderation_state not null default 'pending', created_at timestamptz not null default now(), published_at timestamptz);
create table public.gift_accounts (id uuid primary key default gen_random_uuid(), label text not null, qr_destination text not null, enabled boolean not null default false, state public.publish_state not null default 'draft');
create table public.publication_versions (id uuid primary key default gen_random_uuid(), label text, snapshot jsonb not null default '{}'::jsonb, published_by uuid references public.admin_users(id) on delete set null, created_at timestamptz not null default now());
create table public.admin_audit_logs (id bigint generated always as identity primary key, admin_id uuid references public.admin_users(id) on delete set null, action text not null, entity_type text, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index rsvp_submissions_created_at_idx on public.rsvp_submissions(created_at desc); create index guestbook_status_idx on public.guestbook_messages(status, created_at desc); create index media_assets_checksum_idx on public.media_assets(checksum);

alter table public.site_settings enable row level security; alter table public.couple_profiles enable row level security; alter table public.families enable row level security; alter table public.content_sections enable row level security; alter table public.locations enable row level security; alter table public.events enable row level security; alter table public.event_timeline_items enable row level security; alter table public.albums enable row level security; alter table public.media_assets enable row level security; alter table public.album_photos enable row level security; alter table public.rsvp_submissions enable row level security; alter table public.rsvp_event_selections enable row level security; alter table public.guestbook_messages enable row level security; alter table public.gift_accounts enable row level security; alter table public.publication_versions enable row level security; alter table public.admin_audit_logs enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admin_users where id = auth.uid()) $$;
create policy "admins manage settings" on public.site_settings for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage profiles" on public.couple_profiles for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage families" on public.families for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage sections" on public.content_sections for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage locations" on public.locations for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage events" on public.events for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage timeline" on public.event_timeline_items for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage albums" on public.albums for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage media" on public.media_assets for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage photos" on public.album_photos for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage rsvps" on public.rsvp_submissions for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage selections" on public.rsvp_event_selections for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage messages" on public.guestbook_messages for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage gifts" on public.gift_accounts for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage publications" on public.publication_versions for all using (public.is_admin()) with check (public.is_admin()); create policy "admins view audit logs" on public.admin_audit_logs for select using (public.is_admin());
create policy "public reads approved wishes" on public.guestbook_messages for select using (status = 'approved' and consent_public_display);
